button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #d18d00; outline-offset: 3px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem 0; border-bottom: 1px solid #dce2eb; }
.project-row span { overflow-wrap: anywhere; min-width: 0; }
.project-row button { flex-shrink: 0; }
[role="alert"] { color: #a51d24; }
@media (max-width: 600px) { main { margin: 1rem; padding: 1rem; } }
